```js
function mutate(meta, fn) {
  past.push({ meta: { seq: ++seq, ...meta }, state: snapshot() });
  if (past.length > 60) past.shift();
  future = [];
  fn();
  renderAll();
}
```

undo/redo/reset:
```js
function undo() { if (!past.length) return; const node = past.pop(); future.unshift({ meta: {seq: ++seq, label: "撤销：" + node.meta.label, dim: node.meta.dim, tag: "撤销"}, state: snapshot() }); state = node.state; renderAll(); }
