Ticks helper:
```js
function niceTicks(min, max, n) {
  const span = max - min || 1;
  const step0 = span / n;
  const mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const norm = step0 / mag;
  const step = (norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10) * mag;
  const t0 = Math.ceil(min / step) * step;
  const out = [];
  for (let t = t0; t <= max + 1e-9; t += step) out.push(t);
  return out;
}
function fmt(v, unit) {
  if (Math.abs(v) >= 1000) return (v / 1000).toFixed(v % 1000 ? 1 : 0) + "k";
  if (Math.abs(v) >= 100) return Math.round(v).toString();
  if (Number.isInteger(v)) return String(v);
  return v.toFixed(Math.abs(v) < 10 ? 2 : 1);
}
```

Extents:
```js
function extent(rows, key) { let mn = Infinity, mx = -Infinity; for (const r of rows) { const v = r[key]; if (v < mn) mn = v; if (v > mx) mx = v; } if (!isFinite(mn)) { mn = 0; mx = 1; } if (mn === mx) { mn -= 1; mx += 1; } return [mn, mx]; }
```

Canvas setup helper:
```js
function fitCanvas(cv) { const r = cv.getBoundingClientRect(); const d = window.devicePixelRatio || 1; if (cv.width !== Math.round(r.width * d) || cv.height !== Math.round(r.height * d)) { cv.width = Math.round(r.width * d); cv.height = Math.round(r.height * d); } const ctx = cv.getContext("2d"); ctx.setTransform(d, 0, 0, d, 0, 0); return [ctx, r.width, r.height]; }
```

Scatter geometry recompute needed by interactions: keep last computed {minX,maxX,minY,maxY,x0,y0,w,h,k,cx,cy} in a module var geo.

px↔data:
```js
function toPx(row) { const [mnX,mxX]=geo.ex, ... }
```
I'll store geo = {x0,y0,w,h,ex:[minX,maxX],ey:[minY,maxY]}.
fx = (v-ex0)/(ex1-ex0); X = x0 + ((fx - view.cx) * view.k + 0.5) * w.
Inverse: fx = ((X - x0)/w - 0.5)/view.k + view.cx; v = ex0 + fx*(ex1-ex0).

Zoom on wheel:
```js
const f = e.deltaY < 0 ? 1.18 : 1/1.18;
const k2 = Math.min(8, Math.max(1, view.k * f));
// keep cursor-anchored: cursor fraction u∈[0,1] of plot
const u = (mx - x0)/w, v = (my - y0)/h;
const cu = (u - 0.5)/k + cx; // data-fraction under cursor
cx = cu - (u - 0.5)/k2;
similarly cy.
view.k = k2;
```
