// ---------- 状态 ----------
const INITIAL = {
  proj: { x: "mass", y: "temp", color: "cls", portrait: "radius", sort: "mass", sortDir: -1 },
  filters: [],            // {id, dim, kind:'range', min, max, origin} | {id, dim, kind:'cats', set:string[], origin}
  selection: [],          // 行 id 数组（行级，跨维持久）
