  dimlist: $("#dimlist"), scatter: $("#scatter"), tooltip: $("#tooltip"),
  stageStatus: $("#stage-status"), portrait: $("#portrait"),
  portraitLabel: $("#portrait-label"),
  scrollWrap: $("#table-wrap .scroll"), thead: $("#table-head"), tbody: $("#table-body"),
  tableFoot: $("#table-foot"),
