  mutate({ tag: "投影", label: `${roleName} = ${dimLabel(key)}`, dim: key }, () => {
    const p = state.proj;
    if (role === "x" || role === "y") {
      const other = role === "x" ? "y" : "x";
      if (p[other] === key) p[other] = p[role];   // 换维时占用另一轴 → 互换，避免 x===y
