let hoverId = null;
let drag = null;     // {sx,sy,cx,cy} 框选

function px(v, ex, x0, w, view) { const f = (v - ex[0]) / (ex[1] - ex[0]); return x0 + ((f - view.cx) * view.k + 0.5) * w; }
