function renderScatter(visible) {
  const [ctx, W, H] = fitCanvas(el.scatter);
  const p = state.proj, view = state.view;
  const x0 = 46, x1 = W - 10, y0 = 10, y1 = H - 30;
  const w = x1 - x0, h = y1 - y0;
