  ro.observe($("#scatter-wrap"));
  ro.observe($("#portrait-wrap"));
}

// ---------- 初始化（同步、内联数据 → 首屏即 ready，无加载态） ----------
try {
  // 数值维度预归一化（颜色映射用）
  for (const d of DIMS) {
    if (d.type === "num") {
      const [mn, mx] = extent(ROWS, d.key);
      d._min = mn; d._max = mx; d._norm = v => (v - mn) / (mx - mn || 1);
